CREATE TABLE organizations (
    id          UUID         PRIMARY KEY,
    name        VARCHAR(120) NOT NULL,
    slug        VARCHAR(60)  NOT NULL UNIQUE,
    api_key     VARCHAR(64)  NOT NULL,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT organizations_slug_format CHECK (slug ~ '^[a-z0-9][a-z0-9-]*$')
);

CREATE TABLE app_users (
    id            UUID         PRIMARY KEY,
    org_id        UUID         NOT NULL REFERENCES organizations (id),
    email         VARCHAR(254) NOT NULL UNIQUE,
    display_name  VARCHAR(100) NOT NULL,
    role          VARCHAR(16)  NOT NULL,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT app_users_role_check CHECK (role IN ('ADMIN', 'MEMBER')),
    CONSTRAINT app_users_email_format CHECK (email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$')
);

CREATE INDEX app_users_org_idx ON app_users (org_id);

CREATE TABLE projects (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_id       UUID         NOT NULL REFERENCES organizations (id),
    name         VARCHAR(120) NOT NULL,
    description  TEXT,
    status       VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT projects_status_check CHECK (status IN ('ACTIVE', 'ARCHIVED')),
    CONSTRAINT projects_org_name_unique UNIQUE (org_id, name)
);

CREATE INDEX projects_org_idx ON projects (org_id);

CREATE TABLE documents (
    id           UUID         PRIMARY KEY,
    org_id       UUID         NOT NULL REFERENCES organizations (id),
    project_id   BIGINT       NOT NULL REFERENCES projects (id),
    owner_id     UUID         NOT NULL REFERENCES app_users (id),
    title        VARCHAR(200) NOT NULL,
    body         TEXT         NOT NULL,
    share_token  VARCHAR(64)  NOT NULL,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE INDEX documents_project_idx ON documents (project_id);
CREATE INDEX documents_owner_idx ON documents (owner_id);
